window.hf = (() => {
  // A pad seen by the browser (a real one on this desktop) must not open the pause menu mid-run.
  navigator.getGamepads = () => [];
  const g = window.gerard.game, app = g.app, cam = app.root.findByName('Cámara isométrica');
  const acts = [], lines = [];
  let frame = 0;
  const pre = document.createElement('pre');
  pre.style.cssText = 'position:fixed;right:8px;bottom:128px;z-index:99999;margin:0;padding:6px 8px;max-width:640px;font:11px/1.35 ui-monospace,monospace;color:#fff;background:rgba(0,0,0,.62);border-radius:4px;pointer-events:none;white-space:pre-wrap';
  document.body.append(pre);
  const say = text => { lines.push(text); console.log('[hit-feel]', text); pre.textContent = lines.slice(-4).join('\n'); };
  const stage = () => app.root.findByName('Escenario de combate');
  const pose = () => stage().children.filter(c => c.enabled && c.name !== 'Objetivo').map(c => { const p = c.getPosition(), s = c.getLocalScale(), r = c.getLocalEulerAngles(); return [p.x, p.y, p.z, s.x, s.y, r.x, r.z].map(v => v.toFixed(5)).join(','); }).join('|');
  const ms = frames => Math.round(frames * 1000 / 60);
  const original = g.setBattle;
  g.setBattle = (state, effect, onImpact) => {
    window.hfState = state;
    if (!effect) return original(state, effect, onImpact);
    const a = { n: acts.length, who: effect.actor, kind: effect.skill ?? effect.kind, target: effect.target, start: frame, poses: [] };
    acts.push(a);
    return original(state, effect, () => { a.contact = frame; onImpact?.(); }).then(() => {
      a.done = frame;
      // Frames after contact that showed exactly the contact pose: the hit-stop.
      const i = a.poses.findIndex(p => p.frame === a.contact);
      let held = 0; if (i >= 0) while (a.poses[i + held + 1] && a.poses[i + held + 1].pose === a.poses[i].pose) held++;
      a.held = held;
      const target = state && [...state.allies, ...state.foes].find(c => c.id === a.target);
      const guarded = state?.allies.find(c => c.id === a.target)?.guarding;
      say(`#${a.n} ${a.who} ${a.kind}${a.target ? ' → ' + a.target : ''}${guarded ? ' (guarded)' : ''}${target && target.hp === 0 ? ' (KO)' : ''}: contact +${ms((a.contact ?? NaN) - a.start)} ms · held ${held} frames after it (${ms(held)} ms) · fringe ${(a.fringe ?? 0).toFixed(1)} · resolved +${ms(a.done - a.start)} ms = 1167 + ${ms(a.done - a.start) - 1167} ms`);
    });
  };
  async function step(n = 1) {
    for (let i = 0; i < n; i++) {
      frame++; app.fire("update", 1 / 60);
      const a = acts.at(-1); if (a && a.done === undefined) a.poses.push({ frame, pose: pose() });
      // The post pulse is fired by the contact burst, just after the impact callback.
      for (const b of acts) if (b.contact === frame) b.fringe = g.post.frame.fringing.intensity;
      // A message, not a timer: chained timers get throttled to about one a second in a headless tab.
      await new Promise(r => { const c = new MessageChannel(); c.port1.onmessage = () => r(); c.port2.postMessage(0); });
    }
  }
  return {
    acts, say, step,
    /** Every action's timing at once, for the last shot. */
    summary() { pre.textContent = lines.filter(l => l.startsWith('#') || l.startsWith('post')).join('\n'); },
    freeze() { app.timeScale = 0; },
    /** Steps until the last action is `seconds` in. */
    async to(seconds) { const a = acts.at(-1); while ((frame - a.start) / 60 < seconds - 1e-6) await step(); },
    async untilContact(n) { const end = Date.now() + 60000; while (!acts[n] || acts[n].contact === undefined) {
      // Between actions the interface may be waiting on real time (the enemy plan), so let it run.
      if (!acts[n] && acts.at(-1)?.done !== undefined) await new Promise(r => setTimeout(r, 20));
      await step(); if (Date.now() > end) throw new Error('no contact for action ' + n); } },
    async until(test, max = 1200) { for (let i = 0; i < max && !test(); i++) { await new Promise(r => setTimeout(r, 5)); await step(); } },
    async settle() { const a = acts.at(-1); while (a.done === undefined) await step(); },
    /** One line on what the camera and post pass are doing this frame. */
    probe(label) { const p = cam.getPosition(); say(`${label}: frame ${frame} · fringing ${g.post.frame.fringing.intensity.toFixed(1)} · bloom ${g.post.frame.bloom.intensity.toFixed(3)} · orthoHeight ${cam.camera.orthoHeight.toFixed(3)}`); },
  };
})();

